"""Generate the SYNTHETIC India fixtures. Deterministic: same files every run.

    python3 make_fixtures.py

The numbers are invented. See README.md. Every file written carries
meta.synthetic = true.
"""

import datetime
import json
import os
import random
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(HERE)))   # .claude/skills
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)

from config import india_market as mkt

LAST_DAY = datetime.date(2026, 11, 2)   # a Monday
NOTE = ("SYNTHETIC. Generated by tests/fixtures/india/make_fixtures.py. "
        "These prices never traded. Not market data.")


def sessions_back(n, last=LAST_DAY):
    """The n most recent NSE trading days up to and including `last`."""
    out, d = [], last
    holidays = mkt.load_holidays()
    while len(out) < n:
        ok, _ = mkt.trading_day(d, holidays)
        if ok:
            out.append(d)
        d -= datetime.timedelta(days=1)
    return list(reversed(out))


def bar_times(day, interval_minutes):
    """Every bar OPEN time in a full NSE session, as epoch seconds."""
    n = mkt.bars_per_session(interval_minutes)
    start = mkt.ist_to_utc(datetime.datetime.combine(day, mkt.SESSION_OPEN))
    epoch = int((start - datetime.datetime(1970, 1, 1)).total_seconds())
    return [epoch + i * interval_minutes * 60 for i in range(n)]


def _tick(p):
    return mkt.round_to_tick(p)


def walk(rng, open_price, drift, vol, times, volume=200000):
    """A random walk on the 0.05 tick, each bar a proper o/h/l/c."""
    bars, price = [], open_price
    for t in times:
        o = _tick(price)
        step = rng.gauss(drift, vol)
        c = _tick(max(1.0, o + step))
        hi = _tick(max(o, c) + abs(rng.gauss(0, vol * 0.6)))
        lo = _tick(min(o, c) - abs(rng.gauss(0, vol * 0.6)))
        bars.append({"t": t, "o": o, "h": hi, "l": lo, "c": c,
                     "v": int(volume * (0.6 + rng.random()))})
        price = c
    return bars


def series(symbol, interval, bars, prev_close, extra=None):
    meta = {"synthetic": True, "note": NOTE, "prev_close": prev_close,
            "currency": "INR", "timezone": mkt.IST_NAME, "exchange_name": "NSI"}
    meta.update(extra or {})
    return {"symbol": symbol, "exchange": "NSE", "interval": interval,
            "meta": meta, "bars": bars}


def write(name, payload, compress=False):
    p = os.path.join(HERE, name)
    if compress:
        import gzip as _gz
        body = json.dumps(payload, indent=1, sort_keys=True) + "\n"
        with _gz.open(p + ".gz", "wb") as fh:
            fh.write(body.encode("utf-8"))
        print("wrote %-28s %6d bars (gzipped)" % (name + ".gz", len(payload["bars"])))
        return
    with open(p, "w", encoding="utf-8") as fh:
        json.dump(payload, fh, indent=1, sort_keys=True)
        fh.write("\n")
    print("wrote %-28s %6d bars" % (name, len(payload.get("bars", payload.get("_n", [])))
                                    if isinstance(payload.get("bars"), list) else 0))


def make_reliance_60d():
    rng = random.Random(19)
    bars, price = [], 1480.0
    for day in sessions_back(60):
        day_bars = walk(rng, price, 0.02, 1.1, bar_times(day, 5))
        bars += day_bars
        price = day_bars[-1]["c"]
    write("RELIANCE-5m.json", series("RELIANCE", "5m", bars, 1478.55), compress=True)


def make_reliance_1m():
    rng = random.Random(23)
    bars = walk(rng, 1500.0, 0.004, 0.35, bar_times(LAST_DAY, 1), volume=40000)
    write("RELIANCE-1m.json", series("RELIANCE", "1m", bars, 1496.20))


def make_tcs_orb():
    """A deliberate opening-range breakout, so entry tests have a known answer.

    Opening range is the first 15 minutes, which at 5m is bars 1 to 3
    (09:15, 09:20, 09:25). The 09:45 bar is the first to CLOSE above the
    range high, at a price the test can assert.
    """
    times = bar_times(LAST_DAY, 5)
    rng = random.Random(7)
    bars = []
    # opening range: chop between 4000 and 4020
    for i, t in enumerate(times[:3]):
        o = 4005.0 if i else 4000.0
        bars.append({"t": t, "o": _tick(o), "h": _tick(4020.0 if i == 1 else 4012.0),
                     "l": _tick(3996.0 if i == 2 else 4000.0), "c": _tick(4008.0 + i),
                     "v": 90000 + i * 1000})
    # 09:30 and 09:35 poke at the high but close inside it
    bars.append({"t": times[3], "o": 4010.0, "h": 4022.0, "l": 4008.0, "c": 4018.0, "v": 120000})
    bars.append({"t": times[4], "o": 4018.0, "h": 4021.0, "l": 4014.0, "c": 4019.5, "v": 110000})
    # 09:40 wicks above and closes back under: NOT a trigger
    bars.append({"t": times[5], "o": 4019.5, "h": 4031.0, "l": 4017.0, "c": 4019.0, "v": 180000})
    # 09:45 closes clear of 4020: the trigger, at 4026.50
    bars.append({"t": times[6], "o": 4019.0, "h": 4028.0, "l": 4018.5, "c": 4026.50, "v": 260000})
    price = 4026.50
    for t in times[7:]:
        b = walk(rng, price, 0.05, 1.6, [t])[0]
        bars.append(b)
        price = b["c"]
    write("TCS-5m.json", series("TCS", "5m", bars, 4002.75,
                                {"orb_note": "range high 4020.00; first close above it is the 09:45 bar at 4026.50"}))


def make_circuit_stock():
    """Pinned at the upper circuit: prev close 1000, 10 per cent band, so the
    band is 900 to 1100 and the stock sits at 1100 with no room to move."""
    times = bar_times(LAST_DAY, 5)
    bars = [{"t": t, "o": 1100.0, "h": 1100.0, "l": 1099.95, "c": 1100.0, "v": 5000}
            for t in times]
    write("CIRCUITCO-5m.json", series("CIRCUITCO", "5m", bars, 1000.0,
                                      {"band_pct": 10.0,
                                       "circuit_note": "at the upper circuit all session"}))


def make_yahoo_payload():
    """A raw Yahoo chart payload, with null gaps, to exercise the parser."""
    times = bar_times(LAST_DAY, 5)
    rng = random.Random(31)
    bars = walk(rng, 1500.0, 0.03, 1.0, times)
    o, h, l, c, v = [], [], [], [], []
    for i, b in enumerate(bars):
        if i in (10, 11):            # Yahoo pads missing bars with nulls
            o.append(None); h.append(None); l.append(None); c.append(None); v.append(None)
            continue
        o.append(b["o"]); h.append(b["h"]); l.append(b["l"]); c.append(b["c"]); v.append(b["v"])
    payload = {"chart": {"error": None, "result": [{
        "meta": {"symbol": "RELIANCE.NS", "currency": "INR", "exchangeName": "NSI",
                 "exchangeTimezoneName": mkt.IST_NAME, "gmtoffset": 19800,
                 "previousClose": 1496.20, "synthetic": True, "note": NOTE},
        "timestamp": times,
        "indicators": {"quote": [{"open": o, "high": h, "low": l, "close": c, "volume": v}]}}]}}
    p = os.path.join(HERE, "yahoo-RELIANCE-5m.json")
    with open(p, "w", encoding="utf-8") as fh:
        json.dump(payload, fh, indent=1, sort_keys=True)
        fh.write("\n")
    print("wrote %-28s %6d stamps (2 null)" % ("yahoo-RELIANCE-5m.json", len(times)))


if __name__ == "__main__":
    make_reliance_60d()
    make_reliance_1m()
    make_tcs_orb()
    make_circuit_stock()
    make_yahoo_payload()
    print("\nAll SYNTHETIC. These prices never traded.")
